const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('utf8');

// Search for all warranty records (WR-) and print their full context
const regex = /WR-[A-Z0-9]{6}/g;
let match;
const seen = new Set();
while ((match = regex.exec(text)) !== null) {
  const id = match[0];
  if (seen.has(id)) continue;
  seen.add(id);
  const start = Math.max(0, match.index - 50);
  const end = Math.min(text.length, match.index + 250);
  const snippet = buf.slice(start, end).toString('utf8').replace(/[^\x20-\x7E\n]/g, '|');
  console.log('=== ' + id + ' at offset ' + match.index + ' ===');
  console.log(snippet);
  console.log();
}
"

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('utf8');

// Search more broadly - check if there's any warranty containing E5801A or PROD-73FAB4
const searches = ['E5801A', 'PROD-73FAB4', 'ORD-E0E671'];
for (const term of searches) {
  // Find all WR- entries near this term
  let idx = 0;
  while ((idx = text.indexOf(term, idx)) !== -1) {
    const start = Math.max(0, idx - 500);
    const end = Math.min(text.length, idx + 500);
    const region = buf.slice(start, end).toString('utf8');
    const wrMatches = region.match(/WR-[A-Z0-9]{6}/g);
    if (wrMatches) {
      console.log('Near ' + term + ' at offset ' + idx + ': found warranty refs:', [...new Set(wrMatches)].join(', '));
    }
    idx += term.length;
  }
}

// Also dump ALL warranty records found
console.log('\n=== ALL WARRANTY RECORDS ===');
const wrRegex = /WR-[A-Z0-9]{6}/g;
let m;
const warranties = new Set();
while ((m = wrRegex.exec(text)) !== null) {
  warranties.add(m[0]);
}
console.log([...warranties].join(', '));
"
